def test(Pk,tk):
    cols=[Pb[k] for k in Pk]+[tb[k] for k in tk]
    A=np.array(cols).T
    c,*_=np.linalg.lstsq(A,dP_dt,rcond=None)
    r=A@c-dP_dt
    return np.mean(r**2)/np.var(dP_dt), c
for Pk in [['1','P','P2'],['1','P','P2','sP'],['1','P','sP','lnP'],['1','P','P2','PlnP','sP']]:
    for tk in [['t','st'],['st','s1'],['t','st','lnt'],['t','st','s1','lnt','1/t']]:
        e,c=test(Pk,tk)
        print(Pk,tk,'%.3e'%e)

